actions.script:
const pref = (key) => { const value = ec.user.getPreference(key); return value == null || String(value).trim() === '' ? null : String(value).trim() }
const flag = (key, fallback) => { const value = pref(key); return value == null ? fallback : (value === 'Y' || value === 'true') }
const L = (text) => ec.l10n.localize(text)
let presets = null
try { presets = JSON.parse(pref('CHAT_STATUS_PRESETS') || 'null') } catch (err) { presets = null }
if (!Array.isArray(presets)) presets = [{emoji: '📅', text: L('In a meeting'), clearAfter: '60'}, {emoji: '🚌', text: L('Commuting'), clearAfter: '30'},
    {emoji: '🤒', text: L('Out sick'), clearAfter: 'today'}, {emoji: '🏠', text: L('Working remotely'), clearAfter: 'today'},
    {emoji: '🌴', text: L('On vacation'), clearAfter: '0'}]
const level = pref('CHAT_NOTIFY_DEFAULT')
const minutes = Number(pref('CHAT_AUTO_AWAY_MINUTES'))
const allowedIds = String(pref('CHAT_DND_ALLOWED') || '').split(',').map((id) => id.trim()).filter((id) => id)
const names = {}
if (allowedIds.length) for (const row of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', allowedIds)
        .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list()) names[row.userId] = row.userFullName || row.username
const dndAllowed = allowedIds.filter((id) => names[id]).map((id) => ({userId: id, name: names[id]}))
prefs = {enterSends: flag('CHAT_ENTER_SENDS', true), sounds: flag('CHAT_SOUNDS', true), readReceipts: flag('CHAT_READ_RECEIPTS', true),
    typing: flag('CHAT_TYPING', true), linkPreviews: flag('CHAT_LINK_PREVIEWS', true), notifyDefault: ['all', 'mentions', 'none'].includes(level) ? level : '', notifyPreview: flag('CHAT_NOTIFY_PREVIEW', true),
    autoAwayMinutes: minutes > 0 ? minutes : 10, dndFrom: pref('CHAT_DND_FROM'), dndTo: pref('CHAT_DND_TO'), dndAllowed: dndAllowed,
    statusPresets: presets.filter((item) => item && (item.text || item.emoji)).slice(0, 12).map((item) => ({emoji: String(item.emoji || ''),
        text: String(item.text || ''), clearAfter: String(item.clearAfter ?? '0')}))}

const yn = (value) => value === 'Y' || value === 'true' || value === true ? 'Y' : 'N'
if (saveFlags) {
    ec.user.setPreference('CHAT_ENTER_SENDS', yn(enterSends))
    ec.user.setPreference('CHAT_SOUNDS', yn(sounds))
    ec.user.setPreference('CHAT_READ_RECEIPTS', yn(readReceipts))
    ec.user.setPreference('CHAT_TYPING', yn(typing))
    ec.user.setPreference('CHAT_LINK_PREVIEWS', yn(linkPreviews))
    ec.user.setPreference('CHAT_NOTIFY_PREVIEW', yn(notifyPreview))
} else {
    if (enterSends != null) ec.user.setPreference('CHAT_ENTER_SENDS', yn(enterSends))
    if (sounds != null) ec.user.setPreference('CHAT_SOUNDS', yn(sounds))
    if (readReceipts != null) ec.user.setPreference('CHAT_READ_RECEIPTS', yn(readReceipts))
    if (typing != null) ec.user.setPreference('CHAT_TYPING', yn(typing))
    if (linkPreviews != null) ec.user.setPreference('CHAT_LINK_PREVIEWS', yn(linkPreviews))
    if (notifyPreview != null) ec.user.setPreference('CHAT_NOTIFY_PREVIEW', yn(notifyPreview))
}
if (notifyDefault != null) {
    if (!['', 'all', 'mentions', 'none'].includes(String(notifyDefault))) { ec.message.addError(ec.l10n.localize('Choose all, mentions or nothing')); return }
    ec.user.setPreference('CHAT_NOTIFY_DEFAULT', String(notifyDefault))
}
if (autoAwayMinutes != null && String(autoAwayMinutes) !== '') {
    const minutes = Number(autoAwayMinutes)
    if (!(minutes >= 1 && minutes <= 480)) { ec.message.addError(ec.l10n.localize('Away after 1 to 480 minutes')); return }
    ec.user.setPreference('CHAT_AUTO_AWAY_MINUTES', String(Math.round(minutes)))
}
if (saveDnd) {
    const hhmm = (value) => {
        const text = String(value || '').trim()
        const match = /^(\d{1,2}):(\d{2})/.exec(text)
        if (!match || Number(match[1]) > 23 || Number(match[2]) > 59) return null
        return String(match[1]).padStart(2, '0') + ':' + match[2]
    }
    const from = hhmm(dndFrom), to = hhmm(dndTo)
    if ((dndFrom || dndTo) && !(from && to)) { ec.message.addError(ec.l10n.localize('Give both times of the do not disturb hours, or neither')); return }
    if (from && to && from === to) { ec.message.addError(ec.l10n.localize('The do not disturb hours end when they start')); return }
    ec.user.setPreference('CHAT_DND_FROM', from || '')
    ec.user.setPreference('CHAT_DND_TO', to || '')
}

const current = String(ec.user.getPreference('CHAT_DND_ALLOWED') || '').split(',').map((id) => id.trim()).filter((id) => id)
const id = String(userId || '').trim()
let next
if (action === 'remove') next = current.filter((other) => other !== id)
else if (action === 'add') {
    if (!id || id === ec.user.userId || !ec.entity.find('moqui.security.UserAccount').condition('userId', id).disableAuthz().count()) {
        ec.message.addError(ec.l10n.localize('Choose a person')); return }
    if (current.includes(id)) return
    if (current.length >= 50) { ec.message.addError(ec.l10n.localize('At most 50 people ring through do not disturb')); return }
    next = current.concat([id])
} else { ec.message.addError(ec.l10n.localize('Add or remove a person')); return }
ec.user.setPreference('CHAT_DND_ALLOWED', next.join(','))

const current = ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#ChatPrefs').call().prefs.statusPresets
const list = Array.from(current || [])
if (action === 'add') {
    const shownText = String(text || '').trim(), shownEmoji = String(emoji || '').trim()
    if (!shownText && !shownEmoji) { ec.message.addError(ec.l10n.localize('A status needs a text or an emoji')); return }
    if (Array.from(shownText).length > 100) { ec.message.addError(ec.l10n.localize('A status is up to 100 characters')); return }
    if (Array.from(shownEmoji).length > 16 || /[<>]/.test(shownEmoji)) { ec.message.addError(ec.l10n.localize('An emoji is a few characters')); return }
    if (list.length >= 12) { ec.message.addError(ec.l10n.localize('Twelve presets at most')); return }
    const clear = ['0', '30', '60', '240', 'today', 'week'].includes(String(clearAfter || '0')) ? String(clearAfter || '0') : '0'
    list.push({emoji: shownEmoji, text: shownText, clearAfter: clear})
} else if (action === 'remove') {
    if (index == null || index < 0 || index >= list.length) { ec.message.addError(ec.l10n.localize('No such preset')); return }
    list.splice(index, 1)
} else { ec.message.addError(`Unknown action ${action}`); return }
ec.user.setPreference('CHAT_STATUS_PRESETS', JSON.stringify(list))
statusPresets = list

const presets = Array.from(ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#ChatPrefs').call().prefs.statusPresets || [])
const preset = index != null && index >= 0 ? presets[index] : null
if (!preset) { ec.message.addError(ec.l10n.localize('No such preset')); return }
const params = {statusText: preset.text || '', emoji: preset.emoji || ''}
const clear = String(preset.clearAfter || '0')
if (/^\d+$/.test(clear)) params.clearAfterMinutes = Number(clear)
else {
    // the end of the user's day, or of the week's Sunday: the date in the user's zone, then its last second there
    const today = String(ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'))
    const [year, month, day] = today.split('-').map(Number)
    const civil = new Date(Date.UTC(year, month - 1, day))
    if (clear === 'week') civil.setUTCDate(civil.getUTCDate() + (7 - civil.getUTCDay()) % 7)
    const last = civil.getUTCFullYear() + '-' + String(civil.getUTCMonth() + 1).padStart(2, '0') + '-' + String(civil.getUTCDate()).padStart(2, '0')
    params.clearAtDate = ec.l10n.parseTimestamp(last + ' 23:59:59', 'yyyy-MM-dd HH:mm:ss')
}
const out = ec.service.sync().name('org.moqui.chat.ChatServices.set#UserStatus').parameters(params).call()
if (!ec.message.hasError()) myStatus = out.myStatus

updatedCount = 0; failedCount = 0
const LEVELS = {all: 'CnlAll', mentions: 'CnlMentions', none: 'CnlNone'}
const level = String(ec.user.getPreference('CHAT_NOTIFY_DEFAULT') || '').trim()
if (!LEVELS[level]) { ec.message.addError(ec.l10n.localize('Choose a default notification level first')); return }
const rooms = ec.service.sync().name('org.moqui.chat.ChatServices.find#Rooms').parameter('limit', 1000).call()
if (ec.message.hasError()) return
for (const room of Array.from(rooms.roomList || [])) {
    if (!room.isMember || room.roomTypeEnumId === 'CrtDirect' || room.notificationLevelEnumId === LEVELS[level]) continue
    ec.message.pushErrors()
    try {
        ec.service.sync().name('org.moqui.chat.ChatServices.set#Notification').parameters({chatRoomId: room.chatRoomId,
            notificationLevelEnumId: level}).requireNewTransaction(true).call()
        if (ec.message.hasError()) { failedCount++; ec.logger.warn(`Chat: notification level not set on room ${room.chatRoomId}: ${ec.message.errorsString}`) }
        else updatedCount++
    } catch (err) {
        failedCount++
        ec.logger.warn(`Chat: notification level not set on room ${room.chatRoomId}: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}

dndCount = 0; backCount = 0
const toMinutes = (text) => { const match = /^(\d{1,2}):(\d{2})$/.exec(String(text || '').trim()); return match ? Number(match[1]) * 60 + Number(match[2]) : null }
const users = {}
for (const row of ec.entity.find('moqui.security.UserPreference').condition('preferenceKey', 'in', ['CHAT_DND_FROM', 'CHAT_DND_TO', 'CHAT_DND_AUTO'])
        .disableAuthz().list()) (users[row.userId] = users[row.userId] || {})[row.preferenceKey] = row.preferenceValue
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    for (const userId of Object.keys(users)) {
        const prefs = users[userId]
        const auto = prefs.CHAT_DND_AUTO === 'Y'
        const from = toMinutes(prefs.CHAT_DND_FROM), to = toMinutes(prefs.CHAT_DND_TO)
        if (!auto && (from == null || to == null)) continue
        ec.message.pushErrors()
        try {
            const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).one()
            if (!account || account.disabled === 'Y') continue
            // the user's local time, formatted in the user's zone (with none, the session's). Not
            // ec.user.setTimeZone, which also saves the zone on the signed-in caller's own account.
            const now = toMinutes(ec.l10n.format(ec.user.nowTimestamp, 'HH:mm', null, account.timeZone || null))
            const inside = from != null && to != null && from !== to && (from < to ? (now >= from && now < to) : (now >= from || now < to))
            const status = ec.entity.find('moqui.security.UserStatus').condition('userId', userId).one()
            const statusId = status ? (status.statusEnumId || 'UpsOnline') : 'UpsOnline'
            const setAuto = (value) => {
                const row = ec.entity.makeValue('moqui.security.UserPreference')
                row.setFields({userId: userId, preferenceKey: 'CHAT_DND_AUTO', preferenceValue: value}, true, null, null)
                row.createOrUpdate()
            }
            if (inside && !auto && statusId === 'UpsOnline') {
                ec.service.sync().name('org.moqui.chat.ChatServices.set#UserStatus').parameters({userId: userId, status: 'dnd'}).requireNewTransaction(true).call()
                if (!ec.message.hasError()) { setAuto('Y'); dndCount++ }
            } else if (!inside && auto) {
                if (statusId === 'UpsDnd') ec.service.sync().name('org.moqui.chat.ChatServices.set#UserStatus').parameters({userId: userId, status: 'online'})
                        .requireNewTransaction(true).call()
                if (!ec.message.hasError()) { setAuto('N'); backCount++ }
            }
            if (ec.message.hasError()) ec.logger.error(`Chat do not disturb hours of user ${userId} not applied: ${ec.message.errorsString}`)
        } catch (err) {
            ec.logger.error(`Chat do not disturb hours of user ${userId} not applied: ${err && err.message ? err.message : err}`)
        } finally { ec.message.clearErrors(); ec.message.popErrors() }
    }
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

const appRoot = System.getProperty('comms_app_root') || '/qapps/BasicComms'
const rooms = Array.from(roomList || [])
const wanted = rooms.filter((room) => room.recordEntityName && room.recordId)
        .map((room) => ({recordEntityName: room.recordEntityName, recordId: room.recordId}))
const found = {}
if (wanted.length) {
    const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.lookup#Records').parameters({operation: 'info', records: wanted}).call()
    for (const info of Array.from(out?.recordList || [])) found[info.recordEntityName + '|' + info.recordId] = info
}
roomList = rooms.map((source) => {
    const room = Object.assign({}, source)
    room.url = appRoot + '/Chat?chatRoomId=' + encodeURIComponent(room.chatRoomId)
    room.record = null
    if (room.recordEntityName && room.recordId) {
        const info = found[room.recordEntityName + '|' + room.recordId]
        room.record = info && info.visible ? {visible: true, title: info.title, typeLabel: info.typeLabel || null, url: info.url || null,
            icon: info.icon || 'sym_o_description', entity: info.entity || room.recordEntityName, id: room.recordId}
            : {visible: false, title: room.roomName || room.recordId, typeLabel: null, url: null, icon: 'sym_o_description',
                entity: room.recordEntityName, id: room.recordId}
    }
    return room
})

const account = ec.user.userAccount || {}
me = {userId: ec.user.userId, username: ec.user.username, name: account.userFullName || ec.user.username, partyId: account.partyId || null,
    bridgeAdmin: ec.user.hasPermission('ChatBridgeAdmin')}
prefs = ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#ChatPrefs').call().prefs
// File on a record is offered only with an app that files messages on its records (a record-link provider)
const linkers = ec.service.sync().name('org.moqui.ui.ShellServices.get#Providers').parameter('hook', 'record-link').call()
prefs.recordLink = Array.from(linkers?.providerList || []).length > 0
const out = ec.service.sync().name('org.moqui.chat.ChatServices.find#Rooms').parameter('limit', Math.max(1, Math.min(limit || 200, 500))).call()
if (ec.message.hasError()) return
roomList = ec.service.sync().name('org.moqui.comms.ChatScreenServices.decorate#Rooms').parameter('roomList', out.roomList).call().roomList
unreadTotal = out.unreadTotal
mentionTotal = out.mentionTotal

const out = ec.service.sync().name('org.moqui.chat.ChatServices.find#Rooms').parameters({filter: filter || null, searchText: searchText || null,
    includeJoinable: includeJoinable || joinableOnly, limit: Math.max(1, Math.min(limit || 200, 500))}).call()
if (ec.message.hasError()) return
let list = Array.from(out.roomList || [])
if (joinableOnly) list = list.filter((room) => !room.isMember)
roomList = ec.service.sync().name('org.moqui.comms.ChatScreenServices.decorate#Rooms').parameter('roomList', list).call().roomList

const out = ec.service.sync().name('org.moqui.chat.ChatServices.get#Room').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError() || !out.room) return
member = out.member; access = out.access; memberList = out.memberList
const source = Object.assign({}, out.room)
const me = ec.user.userId
if (!source.roomName) {
    const others = Array.from(memberList || []).filter((item) => item.userId !== me).map((item) => item.name)
    source.displayName = others.length ? others.join(', ') : (Array.from(memberList || []).find((item) => item.userId === me) || {}).name || chatRoomId
} else source.displayName = source.roomName
const otherIds = Array.from(memberList || []).filter((item) => item.userId && item.userId !== me).map((item) => item.userId)
source.otherUserIdList = source.roomTypeEnumId === 'CrtDirect' ? otherIds : []
source.otherUserId = source.roomTypeEnumId === 'CrtDirect' && otherIds.length === 1 ? otherIds[0] : null
room = ec.service.sync().name('org.moqui.comms.ChatScreenServices.decorate#Rooms').parameter('roomList', [source]).call().roomList[0]
timeline = ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#TimelinePage').parameters({chatRoomId: chatRoomId, aroundSeq: aroundSeq ?? null,
    limit: limit}).call().page

const out = ec.service.sync().name('org.moqui.chat.ChatServices.get#Timeline').parameters({chatRoomId: chatRoomId, beforeSeq: beforeSeq ?? null,
    afterSeq: afterSeq ?? null, aroundSeq: aroundSeq ?? null, threadRootEventSeq: threadRootEventSeq ?? null, pinnedOnly: !!pinnedOnly,
    eventSeq: eventSeq ?? null, limit: Math.max(1, Math.min(limit || 50, 200))}).call()
if (ec.message.hasError()) return
const events = Array.from(out.eventList || [])
const ids = new Set()
for (const event of events) {
    if (event.senderUserId) ids.add(event.senderUserId)
    const content = event.content || {}
    for (const key of ['userId', 'byUserId']) if (content[key]) ids.add(String(content[key]))
    for (const id of Array.from(content.userIds || [])) ids.add(String(id))
    for (const reaction of Array.from(event.reactions || [])) for (const id of Array.from(reaction.userIds || [])) ids.add(String(id))
    for (const reaction of Array.from(event.encryptedReactions || [])) if (reaction.senderUserId) ids.add(String(reaction.senderUserId))
    if (event.replyTo && event.replyTo.senderUserId) ids.add(event.replyTo.senderUserId)
    if (event.threadLastUserId) ids.add(event.threadLastUserId)
    if (event.forwardOf && event.forwardOf.senderUserId) ids.add(event.forwardOf.senderUserId)
    if (event.poll) for (const option of Array.from(event.poll.options || [])) for (const id of Array.from(option.voterIds || [])) ids.add(String(id))
}
const userNames = {}
if (ids.size) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', Array.from(ids))
        .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
    userNames[account.userId] = account.userFullName || account.username || account.userId
// the external actors of a bridged room (a reaction's, a membership's): their names on their networks
const actorIds = Array.from(ids).filter((id) => !userNames[id])
for (const event of events) if (event.content && event.content.chatActorId) actorIds.push(String(event.content.chatActorId))
if (actorIds.length) {
    const actors = ec.service.sync().name('org.moqui.chat.ChatServices.get#ActorNames').parameter('chatActorIdList', actorIds).call()?.actorMap || {}
    for (const [id, actor] of Object.entries(actors)) userNames[id] = actor.name
}
page = {room: out.room, access: out.access, eventList: events, hasMoreBefore: !!out.hasMoreBefore, hasMoreAfter: !!out.hasMoreAfter,
    lastReadEventSeq: out.lastReadEventSeq, memberList: out.memberList, userNames: userNames}

userList = []
const me = ec.user.userId
const text = String(term || '').trim().toLowerCase()
const max = Math.max(1, Math.min(limit || 10, 25))
// get#RoomAccess adds no error for a room the user may not read (an error would mark the transaction rollback-only)
const access = ec.service.sync().name('org.moqui.chat.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError() || !access || !access.canRead) return
const out = ec.service.sync().name('org.moqui.chat.ChatServices.get#Room').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError() || !out || !out.room) return
const everyone = Array.from(out.memberList || []).filter((member) => !member.isAgent)
if ((access.canModerate || access.isOwner || everyone.length <= 20) && (!text || 'room'.startsWith(text) || 'everyone'.startsWith(text)))
    userList.push({id: '@room', label: 'room'})
for (const member of Array.from(out.memberList || [])) {
    if (!member.userId || member.userId === me || member.isAgent) continue
    if (text && !String(member.name || '').toLowerCase().includes(text)) continue
    userList.push({id: member.userId, label: member.name})
}
if (out.room.visibilityEnumId === 'CrvUsers' && userList.length < max) {
    const found = ec.service.sync().name('org.moqui.comms.CommsServices.search#Users').parameters({term: text, limit: max}).call()
    for (const user of Array.from(found.userList || [])) {
        if (user.id === me || userList.some((item) => item.id === user.id)) continue
        userList.push({id: user.id, label: user.label})
    }
}
userList = userList.slice(0, max)

const TYPES = {direct: 'CrtDirect', private: 'CrtPrivate', public: 'CrtPublic'}
const type = TYPES[roomTypeEnumId] || roomTypeEnumId
if (!Object.values(TYPES).includes(type)) { ec.message.addError(ec.l10n.localize('A room is direct, private or public')); return }
const ids = Array.from(new Set(Array.from(memberUserIdList || []).concat(memberUserIds ? String(memberUserIds).split(',') : [])
        .map((id) => String(id || '').trim()).filter((id) => id)))
if (type === 'CrtDirect' && !ids.length) { ec.message.addError(ec.l10n.localize('Choose who to message')); return }
let sealed = encrypted == null ? null : !!encrypted
// the default (E2EE by default): a public room is never encrypted
if (sealed == null && type === 'CrtPublic') sealed = false
if (sealed == null && type === 'CrtDirect') {
    // the direct room of these people there is: the encrypted one first, then the plain one (create#Room's keys)
    const people = Array.from(new Set([ec.user.userId].concat(ids))).sort().join(',')
    const existing = (key) => ec.entity.find('moqui.chat.ChatRoom').condition('roomTypeEnumId', 'CrtDirect').condition('directKey', key)
            .disableAuthz().count() > 0
    if (existing('e2ee:' + people)) sealed = true
    else if (existing(people)) sealed = false
}
if (sealed == null) sealed = ec.service.sync().name('org.moqui.chat.ChatKeyServices.check#DevicesReady')
        .parameter('userIdList', ids).call()?.ready === true
const out = ec.service.sync().name('org.moqui.chat.ChatServices.create#Room').parameters({roomTypeEnumId: type, roomName: roomName || null,
    topic: topic || null, memberUserIdList: ids, encrypted: sealed}).call()
reasonCode = out?.reasonCode || null
if (ec.message.hasError()) return
chatRoomId = out.chatRoomId
created = !!out.created
encrypted = sealed

created = false
const looked = ec.service.sync().name('org.moqui.comms.ChatScreenServices.lookup#Records').parameters({operation: 'info',
    records: [{recordEntityName: recordEntityName, recordId: recordId}]}).call()
const info = Array.from(looked?.recordList || [])[0] || null
const entityName = info && info.visible && info.entity ? info.entity : recordEntityName
const existing = ec.service.sync().name('org.moqui.chat.ChatServices.get#Room').parameters({recordEntityName: entityName, recordId: recordId}).call()
if (ec.message.hasError()) return
if (existing.room) { chatRoomId = existing.room.chatRoomId; return }
if (info && !info.visible) { ec.message.addError(ec.resource.expand('Record ${entity} ${id} not found', '', {entity: recordEntityName, id: recordId})); return }
const made = ec.service.sync().name('org.moqui.chat.ChatServices.create#Room').parameters({roomTypeEnumId: 'CrtRecord',
    recordEntityName: entityName, recordId: recordId, roomName: (info && info.title) || recordId}).call()
if (ec.message.hasError()) return
chatRoomId = made.chatRoomId
created = !!made.created

service.description:
Internal: what the apps' record-lookup providers answer (org.moqui.ui.ShellServices.call#Providers,
            hook record-lookup), combined:
            - info: for records [{recordEntityName, recordId}], recordList [{recordEntityName, recordId, entity (the full
              name), visible, title, typeLabel, url, icon}], the first provider's answer for each record;
            - card: for recordEntityName and recordId, the record card (m-record-card) of the first provider with one;
            - search: for text, optionList [{value (entity|id), label}] of every provider, in their order, up to 20;
            - links: for body (a message's HTML), recordList [{entity, id}], the records its links name, up to five.
            A provider that fails is left out (logged by call#Providers); with none, the answers are empty.

actions.script:
recordList = []
optionList = []
card = null
if (!['info', 'card', 'search', 'links'].includes(operation)) { ec.message.addError('Unknown record lookup ' + operation); return }
const out = ec.service.sync().name('org.moqui.ui.ShellServices.call#Providers').parameters({hook: 'record-lookup',
    parameters: {operation: operation, records: records || null, recordEntityName: recordEntityName || null, recordId: recordId || null,
        text: text || null, body: body || null}}).call()
const results = Array.from(out?.results || [])
if (operation === 'info') {
    const seen = new Set()
    for (const result of results) for (const info of Array.from(result.recordList || [])) {
        const key = info.recordEntityName + '|' + info.recordId
        if (seen.has(key)) continue
        seen.add(key)
        recordList.push(info)
    }
} else if (operation === 'card') {
    card = results.map((result) => result.card).find((found) => found && Object.keys(found).length) || null
} else if (operation === 'search') {
    for (const result of results) for (const option of Array.from(result.optionList || [])) if (optionList.length < 20) optionList.push(option)
} else {
    const seen = new Set()
    for (const result of results) for (const record of Array.from(result.recordList || [])) {
        const key = record.entity + '|' + record.id
        if (seen.has(key) || recordList.length >= 5) continue
        seen.add(key)
        recordList.push({entity: record.entity, id: record.id})
    }
}

uploadList = []; failedList = []
const files = (Array.isArray(file) ? file : [file]).filter((item) => item != null && typeof item === 'object')
if (uploadId) files.push({uploadId: String(uploadId), name: String(uploadId)})
if (!files.length) { ec.message.addError(ec.l10n.localize('No file uploaded')); return }
for (const item of files) {
    const name = String(item.name || item.fileName || 'file')
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('org.moqui.chat.ChatServices.upload#Attachment').parameters(item.uploadId
            ? {chatRoomId: chatRoomId, uploadId: item.uploadId} : {chatRoomId: chatRoomId, file: item})
                .requireNewTransaction(true).call()
        if (ec.message.hasError()) failedList.push({fileName: name, error: ec.message.errorsString})
        else uploadList.push({chatAttachmentId: out.chatAttachmentId, fileName: out.fileName, contentType: out.contentType, fileSize: out.fileSize})
    } catch (err) {
        failedList.push({fileName: name, error: err && err.message ? err.message : String(err)})
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
for (const failed of failedList) ec.logger.warn(`Chat: file ${failed.fileName} not stored in room ${chatRoomId}: ${failed.error}`)
if (!uploadList.length && failedList.length) ec.message.addError(failedList[0].error)

rows = []
const chatUrl = (System.getProperty('comms_app_root') || '/qapps/BasicComms') + '/Chat'
moreUrl = chatUrl
const L = (text) => ec.l10n.localize(text)
const term = String(text || '').replace(/^#/, '').trim()
const max = Math.max(1, Math.min(limit || 5, 20))
const me = ec.user.userId
ec.message.pushErrors()
try {
    const out = ec.service.sync().name('org.moqui.chat.ChatServices.find#Rooms').parameters({searchText: term || null, includeJoinable: true,
        limit: max}).call()
    if (ec.message.hasError()) { ec.logger.warn(`Palette chat rooms for ${term} failed: ${ec.message.errorsString}`); return }
    // a private room is not a lock: a lock means end-to-end encrypted only (Comms-Messaging §6.1 rule 6)
    const kinds = {CrtDirect: ['sym_o_person', 'Direct message'], CrtPrivate: ['sym_o_groups', 'Private room'], CrtPublic: ['sym_o_tag', 'Public room'],
        CrtRecord: ['sym_o_description', 'Record room'], CrtExternal: ['sym_o_sms', 'Phone number']}
    const seen = new Set()
    const addRoom = (room) => {
        if (seen.has(room.chatRoomId) || rows.length >= max) return
        seen.add(room.chatRoomId)
        const kind = kinds[room.roomTypeEnumId] || ['sym_o_chat', 'Room']
        const parts = [L(kind[1])]
        if (room.encrypted) parts.push(L('End-to-end encrypted'))
        if (!room.isMember) parts.push(L('not joined'))
        if (room.unreadCount) parts.push(ec.resource.expand('${count} unread', '', {count: room.unreadCount}))
        if (room.topic) parts.push(room.topic)
        rows.push({title: room.displayName, subtitle: parts.join(' · '), icon: kind[0], url: chatUrl + '?chatRoomId=' + encodeURIComponent(room.chatRoomId)})
    }
    Array.from(out.roomList || []).forEach(addRoom)
    // a number typed as it is written (+1 555-0100, (555) 0100): the user's phone rooms whose number has its digits, by
    // the room's number and its bridge's (externalRoomId ours/theirs), of all the user's rooms
    const digits = term.replace(/[^0-9]/g, '')
    if (rows.length < max && digits.length >= 3 && /^\+?[0-9 ().-]+$/.test(term) && me) {
        const myRooms = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', me).condition('leftDate', null)
                .selectField('chatRoomId').disableAuthz().list()).map((row) => row.chatRoomId)
        const phoneRooms = myRooms.length ? Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', myRooms)
                .condition('roomTypeEnumId', 'CrtExternal').condition('archivedDate', null).selectField('chatRoomId').selectField('roomName')
                .selectField('topic').selectField('lastEventDate').disableAuthz().list()) : []
        const byId = {}
        for (const row of phoneRooms) byId[row.chatRoomId] = row
        const found = new Set(phoneRooms.filter((row) => String(row.roomName || '').replace(/[^0-9]/g, '').includes(digits)).map((row) => row.chatRoomId))
        if (phoneRooms.length) for (const bridge of ec.entity.find('moqui.chat.ChatRoomBridge').condition('chatRoomId', 'in', Object.keys(byId))
                .condition('externalRoomId', 'like', '%/%' + digits + '%').selectField('chatRoomId').disableAuthz().list()) found.add(bridge.chatRoomId)
        Array.from(found).map((id) => byId[id]).sort((left, right) => Number(right.lastEventDate || 0) - Number(left.lastEventDate || 0))
            .forEach((row) => addRoom({chatRoomId: row.chatRoomId, roomTypeEnumId: 'CrtExternal', displayName: row.roomName || row.chatRoomId,
                isMember: true, topic: row.topic || null}))
    }
} catch (err) {
    ec.logger.warn(`Palette chat rooms for ${term} failed: ${err && err.message ? err.message : err}`)
} finally { ec.message.clearErrors(); ec.message.popErrors() }

rows = []
const chatUrl = (System.getProperty('comms_app_root') || '/qapps/BasicComms') + '/Chat'
const L = (text) => ec.l10n.localize(text)
const term = String(text || '').trim()
const max = Math.max(1, Math.min(limit || 5, 20))
const me = ec.user.userId
if (!term || !me) return
ec.message.pushErrors()
try {
    const people = Array.from(ec.service.sync().name('org.moqui.comms.CommsServices.search#Users').parameters({term: term, limit: max}).call()?.userList || [])
            .filter((person) => person.id && person.id !== me)
    if (ec.message.hasError() || !people.length) return
    const myRooms = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', me).condition('leftDate', null)
            .selectField('chatRoomId').disableAuthz().list()).map((row) => row.chatRoomId)
    const direct = myRooms.length ? Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', myRooms)
            .condition('roomTypeEnumId', 'CrtDirect').selectField('chatRoomId').disableAuthz().list()).map((row) => row.chatRoomId) : []
    const membersOf = {}
    if (direct.length) for (const row of ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', 'in', direct)
            .selectField('chatRoomId').selectField('userId').disableAuthz().list())
        if (row.userId) (membersOf[row.chatRoomId] = membersOf[row.chatRoomId] || []).push(row.userId)
    // a direct chat of the two of them (a group's direct chat is not that person's own)
    const withRoom = new Set()
    for (const ids of Object.values(membersOf)) {
        const others = Array.from(new Set(ids)).filter((id) => id !== me)
        if (others.length === 1) withRoom.add(others[0])
    }
    for (const person of people) {
        if (rows.length >= max) break
        if (withRoom.has(person.id)) continue
        rows.push({title: person.label, subtitle: L('Person') + ' · ' + L('Write a direct message'), icon: 'sym_o_person_add',
            url: chatUrl + '?dm=' + encodeURIComponent(person.id) + '&dmName=' + encodeURIComponent(person.label || '')})
    }
} catch (err) {
    ec.logger.warn(`Palette people for ${term} failed: ${err && err.message ? err.message : err}`)
} finally { ec.message.clearErrors(); ec.message.popErrors() }

items = []; nextCursor = null
const me = ec.user.userId
if (!me) return
const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const size = Math.max(1, Math.min(100, Number(limit) || 40))
const cf = ec.entity.conditionFactory
const decode = (text) => {
    const parts = String(text || '').split('~')
    if (parts.length < 3 || !/^\d+$/.test(parts[0]) || !/^\d+$/.test(parts[1])) return null
    return {date: Number(parts[0]), eventSeq: Number(parts[1]), chatRoomId: parts.slice(2).join('~')}
}
const encode = (row) => [toMillis(row.threadLastDate), Number(row.eventSeq), row.chatRoomId].join('~')
let at = cursor ? decode(cursor) : null
if (cursor && !at) { ec.message.addError(ec.l10n.localize('This list was changed: read it again from the start')); return }
// the threads I replied in, by room (at most the latest 2000 of my replies)
const repliedIn = {}
for (const row of ec.entity.find('moqui.chat.ChatEvent').condition('senderUserId', me).condition('threadRootEventSeq', 'not-equals', null)
        .selectField('chatRoomId').selectField('threadRootEventSeq').distinct(true).orderBy('-threadRootEventSeq').limit(2000).disableAuthz().list())
    (repliedIn[row.chatRoomId] = repliedIn[row.chatRoomId] || new Set()).add(Number(row.threadRootEventSeq))
const mine = [cf.makeCondition('senderUserId', 'equals', me)]
for (const roomId of Object.keys(repliedIn)) mine.push(cf.makeCondition([cf.makeCondition('chatRoomId', 'equals', roomId),
    cf.makeCondition('eventSeq', 'in', Array.from(repliedIn[roomId]))], 'and'))
const after = (point) => cf.makeCondition([cf.makeCondition('threadLastDate', 'less', String(point.date)),
    cf.makeCondition([cf.makeCondition('threadLastDate', 'equals', String(point.date)), cf.makeCondition([
        cf.makeCondition('chatRoomId', 'less', point.chatRoomId),
        cf.makeCondition([cf.makeCondition('chatRoomId', 'equals', point.chatRoomId), cf.makeCondition('eventSeq', 'less', point.eventSeq)], 'and')], 'or')], 'and')], 'or')
const readable = {}
const canRead = (roomId) => {
    if (!(roomId in readable)) {
        const access = ec.service.sync().name('org.moqui.chat.ChatServices.get#RoomAccess').parameter('chatRoomId', roomId).call()
        readable[roomId] = access && access.canRead ? access.room : null
    }
    return readable[roomId]
}
// read in batches until the page is full and one more is seen (rooms no longer readable are left out, and the
// cursor goes on past them), ten batches at most
const kept = []
let last = null
let more = false
const BATCH = Math.max(50, size + 1)
for (let round = 0; round < 10 && !more; round++) {
    let find = ec.entity.find('moqui.chat.ChatEvent').condition('eventTypeEnumId', 'CetMessage').condition('threadRootEventSeq', null)
            .condition('threadReplyCount', 'greater', 0).condition('threadLastDate', 'not-equals', null).condition(cf.makeCondition(mine, 'or'))
    if (at) find = find.condition(after(at))
    const batch = Array.from(find.orderBy('-threadLastDate').orderBy('-chatRoomId').orderBy('-eventSeq').limit(BATCH).disableAuthz().list())
    for (const row of batch) {
        if (kept.length === size) { more = true; break }
        last = row
        if (canRead(row.chatRoomId)) kept.push(row)
    }
    if (more || batch.length < BATCH) break
    at = decode(encode(last))
    if (round === 9) more = true
}
if (more && last) nextCursor = encode(last)
if (!kept.length) return
// what each thread shows: its root and last reply (as the room's lists summarize them), who replied, names
const byRoom = {}
for (const row of kept) (byRoom[row.chatRoomId] = byRoom[row.chatRoomId] || []).push(row)
const summaries = {}
const repliers = {}
for (const roomId of Object.keys(byRoom)) {
    const rows = byRoom[roomId]
    summaries[roomId] = ec.service.sync().name('org.moqui.chat.ChatServices.get#MessageSummaries').parameters({chatRoomId: roomId,
        eventSeqList: rows.map((row) => Number(row.eventSeq)).concat(rows.filter((row) => row.threadLastEventSeq != null).map((row) => Number(row.threadLastEventSeq)))})
            .call()?.summaryMap || {}
    for (const reply of ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', roomId).condition('threadRootEventSeq', 'in', rows.map((row) => Number(row.eventSeq)))
            .condition('senderUserId', 'not-equals', me).selectField('threadRootEventSeq').selectField('senderUserId').distinct(true).disableAuthz().list())
        if (reply.senderUserId) (repliers[roomId + ' ' + Number(reply.threadRootEventSeq)] = repliers[roomId + ' ' + Number(reply.threadRootEventSeq)] || new Set()).add(reply.senderUserId)
}
const userIds = Array.from(new Set(kept.flatMap((row) => [row.senderUserId, row.threadLastUserId]).filter((id) => id)))
const names = {}
if (userIds.length) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', userIds)
        .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
    names[account.userId] = account.userFullName || account.username || account.userId
for (const row of kept) {
    const room = readable[row.chatRoomId]
    const sealed = !!room.encrypted
    const map = summaries[row.chatRoomId]
    const root = map[String(Number(row.eventSeq))] || {}
    const lastReply = row.threadLastEventSeq != null ? map[String(Number(row.threadLastEventSeq))] || {} : {}
    items.push({chatRoomId: row.chatRoomId, roomName: room.roomName ?? null, roomTypeEnumId: room.roomTypeEnumId ?? null,
        threadRootEventSeq: Number(row.eventSeq), startedByMe: row.senderUserId === me,
        rootSenderName: row.senderUserId ? names[row.senderUserId] || row.senderUserId : null, rootSnippet: sealed ? null : root.snippet ?? null,
        replyCount: Number(row.threadReplyCount || 0), lastDate: toMillis(row.threadLastDate),
        lastEventSeq: row.threadLastEventSeq != null ? Number(row.threadLastEventSeq) : null, lastUserId: row.threadLastUserId ?? null,
        lastUserName: row.threadLastUserId ? names[row.threadLastUserId] || row.threadLastUserId : null,
        lastSnippet: sealed ? null : lastReply.snippet ?? null, replierCount: (repliers[row.chatRoomId + ' ' + Number(row.eventSeq)] || new Set()).size,
        encrypted: sealed, encryptedContent: sealed ? lastReply.encrypted ?? null : null,
        encryptedEventSeq: sealed ? lastReply.encryptedEventSeq ?? null : null, encryptedSentDate: sealed ? lastReply.encryptedSentDate ?? null : null})
}

mailList = []
const me = ec.user.userId
if (!me) return
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const lower = (text) => String(text || '').trim().toLowerCase()
// the addresses of a To or Cc text ("Name" <a@b>, c@d), in lower case
const addressesOf = (text) => {
    const out = []
    let current = '', quote = false, angle = 0
    for (const ch of String(text || '')) {
        if (ch === '"') quote = !quote
        else if (ch === '<' && !quote) angle++
        else if (ch === '>' && !quote && angle > 0) angle--
        else if ((ch === ',' || ch === ';') && !quote && angle === 0) { out.push(current); current = ''; continue }
        current += ch
    }
    out.push(current)
    return out.map((entry) => { const match = /<([^>]+)>\s*$/.exec(entry); return lower(match ? match[1] : entry.replace(/^"|"$/g, '')) }).filter((one) => one)
}
// the people of my direct chats of two: the other member, a user of this server
const myRooms = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', me).condition('leftDate', null)
        .selectField('chatRoomId').disableAuthz().list()).map((row) => row.chatRoomId)
if (!myRooms.length) return
// a person's plain and encrypted direct chats both get the line
const directAll = Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', myRooms).condition('roomTypeEnumId', 'CrtDirect')
        .selectField('chatRoomId').disableAuthz().list()).map((row) => row.chatRoomId)
if (!directAll.length) return
const membersOf = {}
for (const row of ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', 'in', directAll).selectField('chatRoomId').selectField('userId')
        .disableAuthz().list()) if (row.userId) (membersOf[row.chatRoomId] = membersOf[row.chatRoomId] || new Set()).add(row.userId)
const roomsOf = {}
for (const roomId of Object.keys(membersOf)) {
    const others = Array.from(membersOf[roomId]).filter((id) => id !== me)
    if (others.length === 1) (roomsOf[others[0]] = roomsOf[others[0]] || []).push(roomId)
}
const people = Object.keys(roomsOf)
if (!people.length) return
// the mail I may read, and my own addresses (a person never matches by one of mine)
const access = ec.service.sync().name('org.moqui.mail.EmailClientServices.get#EmailAccountAccess').call() || {}
const accountIds = Array.from(access.accountList || []).filter((account) => !account.isInternal && account.level >= 1).map((account) => account.emailAccountId)
if (!accountIds.length) return
const mine = new Set([lower(ec.user.userAccount?.emailAddress)])
for (const account of Array.from(access.accountList || [])) mine.add(lower(account.emailAddress))
// each person's address: their user account's alone
const addressOwner = {}
for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', people).selectField('userId').selectField('emailAddress')
        .disableAuthz().list()) {
    const one = lower(account.emailAddress)
    if (one && one.includes('@') && !mine.has(one) && !addressOwner[one]) addressOwner[one] = account.userId
}
const addresses = Object.keys(addressOwner)
if (!addresses.length) return
const cf = ec.entity.conditionFactory
// the address as a whole entry of a To or Cc list ("Name" <a@b>, a@b, c@d): alone, in angle brackets, first, or after
// a comma, so a longer address that ends with it (xa@b) is not taken; each match is checked again below
const escaped = (address) => address.replace(/[\\%_]/g, '\\$&')
const listMatches = (field, address) => {
    const one = escaped(address)
    return [cf.makeCondition(field, 'equals', address).ignoreCase()].concat(['%<' + one + '>%', one + ',%', '%,' + one, '%, ' + one,
        '%,' + one + ',%', '%, ' + one + ',%'].map((pattern) => cf.makeCondition(field, 'like', pattern).ignoreCase()))
}
const matches = []
for (const address of addresses) {
    matches.push(cf.makeCondition('fromAddress', 'equals', address).ignoreCase())
    matches.push(...listMatches('toAddresses', address), ...listMatches('ccAddresses', address))
}
const leftOut = Array.from(ec.entity.find('moqui.basic.email.EmailFolder').condition('emailAccountId', 'in', accountIds)
        .condition('folderKindEnumId', 'in', ['EfkTrash', 'EfkJunk']).selectField('emailFolderId').disableAuthz().list()).map((row) => row.emailFolderId)
const since = String(Date.now() - 180 * 86400000)
let find = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailAccountId', 'in', accountIds)
        .condition('messageDate', 'greater-equals', since).condition('statusId', 'not-equals', 'ES_DRAFT', true)
        .condition(cf.makeCondition(matches, 'or'))
if (leftOut.length) find = find.condition(cf.makeCondition([cf.makeCondition('emailFolderId', 'not-in', leftOut), cf.makeCondition('emailFolderId', 'equals', null)], 'or'))
const found = Array.from(find.selectField('emailMessageId').selectField('rootEmailMessageId').selectField('subject').selectField('messageDate')
        .selectField('sentDate').selectField('fromAddress').selectField('toAddresses').selectField('ccAddresses')
        .orderBy('-messageDate').limit(300).disableAuthz().list())
const inbox = (System.getProperty('comms_app_root') || '/qapps/BasicComms') + '/Inbox'
const done = new Set()
for (const message of found) {
    const involved = [lower(message.fromAddress)].concat(addressesOf(message.toAddresses), addressesOf(message.ccAddresses))
    for (const address of involved) {
        const userId = addressOwner[address]
        if (!userId || done.has(userId)) continue
        done.add(userId)
        const threadKey = 'email:' + (message.rootEmailMessageId || message.emailMessageId)
        for (const chatRoomId of roomsOf[userId]) mailList.push({userId: userId, chatRoomId: chatRoomId, subject: message.subject ?? null,
            date: toMillis(message.messageDate) ?? toMillis(message.sentDate), threadKey: threadKey,
            url: inbox + '?view=all&thread=' + encodeURIComponent(threadKey)})
    }
    if (done.size === people.length) break
}
